import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec4, float, mix, uniform, time } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.6;
  const height = 1.0;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);
  const material = new THREE.MeshStandardNodeMaterial({
    metalness: 0.5,
    roughness: 0.55,
  });

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
    map.wrapS = THREE.RepeatWrapping;
    map.wrapT = THREE.RepeatWrapping;
  }

  const uvNode = uv();
  const baseTex = texture(map, uvNode);

  const ink = vec4(0x16 / 255, 0x16 / 255, 0x1d / 255, 1.0);
  const paper = vec4(0xe8 / 255, 0xec / 255, 0xf2 / 255, 1.0);

  // engineered gradient: linear blend across Y based on uv, combined with brushed metal texture
  const gradientFactor = uvNode.y.clamp(0.0, 1.0);
  const gradient = mix(ink, paper.mul(0.35).add(ink.mul(0.65)), gradientFactor);

  // subtle grain via pseudo-random noise from uv + time (static-ish, low amplitude)
  const grainSeed = uvNode.x.mul(1237.13).add(uvNode.y.mul(917.71));
  const grain = grainSeed.sin().mul(43758.5453).fract().sub(0.5).mul(0.035);

  const combined = baseTex.mul(0.6).add(gradient.mul(0.4));
  const withGrain = vec4(combined.rgb.add(grain), 1.0);

  material.colorNode = withGrain;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  return mesh;
}
